import hashlib,json,statistics,sys
from campaign import HERE,ROOT,CACHE
s=json.loads((HERE/'summary-phase4.json').read_text()); selected=s['selected']
caption='Machine/conditions: Mac mini Apple M4, 10 GPU cores, 24 GiB unified; macOS 15.4.1 (24E263), AC power, Parallels VM running and untouched, 2026-11-09. Kernel GPU timestamps, 2 warmups; 7 timed runs per current full-grid arm and each CPU-contention row, 5 per sweep G and each old-3b row. Per-campaign idle, thermal, power and SHA records plus per-row foreign GPU accounting and IOReport residency are retained in runs-phase4.jsonl/summary-phase4.json. Foreign percentages shown are selected-attempt values.'
def table(head): return '\n'+caption+'\n\n'+head+'\n'
def sel(tag): return sorted((a for a in selected if a['tag']==tag),key=lambda a:a['G'])
def extent(a,field='gpu_s',scale=1000):
 r=a[field]; return f"{r['median']*scale:.3f} ({r['min']*scale:.3f}–{r['max']*scale:.3f})"
def clockcells(a):
 f=a['gpu_frequency']; c=a['clock_attribution']; return f"{f['f_avg_active_mhz']:.2f} | {c['p15_to_kernel_ratio']:.4f} | {'yes' if c['p15_ge_95pct'] else 'no'} | {c['kernel_attributed_mhz']:.2f}"
def costs(a): return f"{a['k_cycles_avg']:.2f} | {a['k_cycles_attributed']:.2f}"
text='\n\n## Phase 4 — 2026-11-09, D2 remaining kernels, CPU contention and clock attribution\n\n'
text+='This section appends new evidence to the accepted Phase 0–3b record. The original report prefix and old runs are preserved. The shared prep cache had been deleted after the prior campaign; committed campaign.py prep regenerated it from the same local Qwen3 tensors. Again, all 28,584 shared streams round-trip through the unchanged ordinary native decoder. No model downloads, installs, sudo, git commands or shipped-source edits were used. Baseline for this round is 148 tests: 142 passed and six custom Skip exceptions reported as failures by pytest.\n\n'
text+='The new harness compiles the shipped Metal source unchanged at runtime; stride modes append wrapper-only source generated by build_phase4_wrappers.py. Both the perstream and fused wrapper stream bodies are extracted verbatim. The only stream-body change is replacing gid initialization by a grid-stride loop. Perstream table construction remains inside the stream body; fused shared-LUT construction stays before the loop. There is no threadgroup_barrier in either stream body, only simdgroup_barrier. Source/body hashes are in wrapper-phase4-audit.json.\n\n'
p=s['perstream_prep']; d=s.get('perstream_drift',{}); cost=s.get('per_chunk_metal_cost_evidence',{})
text+='### 1. Ordinary per-chunk-table streams\n\n'
text+=f"All {p['nstr']:,} × {p['plane']:,} B exponent streams are independently encoded by native lmz_rans_encode, each with its own 516-byte header, and every stream is verified by untouched lmz_rans_decode. Plain bytes: {p['plain_bytes']:,}; coded bytes including all stream headers: {p['coded_bytes']:,}; padded payload: {p['padded_payload_bytes']:,}; expansion {p['expansion']:.6f}. The source tensors/partial final tensor are the same as Phase 1 and listed in summary-phase4.json. The fixture's unused shared-header slot is zero; each actual ordinary payload starts with R1. Alignment padding is a harness artifact, not additional codec metadata.\n\n"
text+=table('| Arm | Median GPU ms (min–max) | Plain GB/s | TG threads | Compiled TG bytes | Foreign % |\n|---|---:|---:|---:|---:|---:|')
for tag,title in [('perstream-shipped','Shipped full grid, G=7146'),('perstream-drift','Stride full grid, G=7146')]:
 for a in sel(tag): text+=f"| {title} | {extent(a)} | {a['gbps']['median']:.4f} | {a['threads_per_tg']} | {a['static_threadgroup_bytes']} | {100*a['foreign_fraction']:.2f} |\n"
if d: text+=f"\nDrift = {100*d['relative_drift']:.3f}%, within 3%; sweep permitted. Shipped geometry is exactly 32 threads/TG, four streams/TG, ceil(28,584/4)=7,146 TGs. The compiled 20,992 B agrees with 16,384 B symbols + 4,096 B per-group start/frequency tables + 512 B staging.\n\n"
text+=table('| G | GPU ms | Plain GB/s (min–max) | GB/s per launched TG | k_ns† | k_avg† cycles/B | k_attributed† cycles/B | Foreign % |\n|---:|---:|---:|---:|---:|---:|---:|---:|')
for a in sel('perstream-sweep'):
 r=a['gbps']; valid=a['G']<=30
 ns=f"{a['k_ns_apparent']:.2f}" if valid else '—'
 ka=f"{a['k_cycles_avg']:.2f}" if valid else '—'; kt=f"{a['k_cycles_attributed']:.2f}" if valid else '—'
 text+=f"| {a['G']} | {a['gpu_s']['median']*1000:.3f} | {r['median']:.4f} ({r['min']:.4f}–{r['max']:.4f}) | {a['per_launched_tg_gbps']:.6f} | {ns} | {ka} | {kt} | {100*a['foreign_fraction']:.2f} |\n"
if cost:
 text+=f"\n†Only low-grid rows G≤30 interpret G as resident TGs: resident_lanes=32G, k_ns=32G/rate_GBps, k_avg=k_ns×f_avg_active_MHz/1000, k_attributed=k_ns×kernel_attributed_MHz/1000. G={cost['linear_G']} fits a through-origin slope of {cost['slope_gbps_per_tg']:.6f} GB/s/TG, max relative residual {100*cost['max_relative_linear_residual']:.3f}%. Across G={cost['k_G']}, k_ns={cost['k_ns_interval'][0]:.2f}–{cost['k_ns_interval'][1]:.2f}, average-active k={cost['k_cycles_avg_interval'][0]:.2f}–{cost['k_cycles_avg_interval'][1]:.2f}, and **kernel-attributed k={cost['k_cycles_attributed_interval'][0]:.2f}–{cost['k_cycles_attributed_interval'][1]:.2f} lane-cycles per decoded exponent byte**. This is the per-chunk Metal evidence missing from cost_model; no shipped cost-model edit is made here.\n\n"
text+='The higher-grid curve is not a simple saturation plateau. It accelerates beyond G=30 and reaches about 10.56 GB/s around G=100, then falls toward the full-grid rate near 4.5 GB/s. The supplied separate probe reported three 20,992-B TGs per core, but **this decoder sweep does not independently validate a 30-TG residency ceiling**. At the low-grid slope, 10.56 GB/s corresponds to roughly 73 useful TG-equivalents, inconsistent with naively capping active TGs at 30 without another performance effect. Scheduling, occupancy-sensitive latency hiding, cache/table construction and compiler behavior are not separated by this campaign. The wrapper passed the required full-grid drift and all byte checks; a full-grid pass alone does not prove compiler equivalence at every low-grid occupancy. No single full-grid fit is substituted for the measured low-grid interval, and no unsupported pool size or residency is published as fact.\n\n'
text+='### 4. Clock attribution, including the old Phase-3b rows\n\n'
text+='The rule requested in D2 is applied to every new row and re-read from every old Phase-3b attempt: use P15 MHz iff P15 residency ≥ 0.95 × summed timed kernel GPU seconds; otherwise use measured f_avg_active. The condition, ratio and chosen clock are printed below. P15 is 1578 MHz from IORegistry pmgr voltage-states9. The P-state table is non-monotonic in index order and is kept indexed as supplied. gpufreq.py remains unchanged. A residency-weighted average includes lower-state/background time between dispatches and can under-read the kernel clock; the P15 rule is an attribution criterion, not a hardware per-kernel timestamp or proof that foreign work contributed zero P15 time. Both estimates are retained. No clock telemetry exists for pre-3b runs, so none is assigned retroactively.\n\n'
old=s.get('old3b_clock_attribution',{})
text+=table('| Old 3b G | f_avg active MHz | P15 s / kernel s | P15 ≥95%? | Attributed MHz | k_avg‡ | k_attributed‡ |\n|---:|---:|---:|---|---:|---:|---:|')
for a in old.get('selected_rows',[]): text+=f"| {a['G']} | {clockcells(a)} | {costs(a)} |\n"
text+='\n‡Old shared rows use R=min(G,40) TGs and 128 lanes/TG; above the first bend those are apparent costs conditional on the prior 40-TG inference, not additional compute-bound measurements. All attempts, not only selected retries, are in clock-attribution-phase4-old3b.json. The manager’s approximately 269 cycles/B at G=1 and 313 at G=40 are confirmed: 269.42 and 313.15. At G=40 the average-active estimate is only 299.49. Thus the previous f_avg-active ceiling cannot simply be read as a kernel-clock-attributed ceiling. This correction does not modify the shipped shared cost record.\n\n'
text+=table('| New tag / G | f_avg active MHz | P15 s / kernel s | P15 ≥95%? | Attributed MHz | k_avg§ | k_attributed§ |\n|---|---:|---:|---|---:|---:|---:|')
for a in selected:
 # Every row receives both clocks. Above an unvalidated resident cap express
 # costs symbolically, rather than silently presenting launched lanes as resident.
 if a['mode'].startswith('perstream') and a['G']>30:
  unit_avg=a['threads_per_tg']/a['exponent_gbps']['median']*a['gpu_frequency']['f_avg_active_mhz']/1000
  unit_attr=a['threads_per_tg']/a['exponent_gbps']['median']*a['clock_attribution']['kernel_attributed_mhz']/1000
  k=f"R×{unit_avg:.4f} | R×{unit_attr:.4f}"
 else: k=costs(a)
 text+=f"| {a['tag']} / {a['G']} | {clockcells(a)} | {k} |\n"
text+='\n§Unit is lane-cycles per exponent-plane decoded byte. For shared/fused apparent costs R=min(G,40) is an explicit curve-derived assumption; saturated or contended rows do not isolate compute cost. Fused per-BF16-output-byte cost would be half these numbers. For perstream G≤30 use R=G; above it R is left symbolic, because actual resident TG count is unresolved, and each multiplier is the measured lane-cycle coefficient per resident TG. New raw records retain the separate launched-lane diagnostic too; it is not a valid cost when launched TGs are not all resident. All state durations and both clock inputs are in each row; group-level accounting repeated on member dispatches must not be summed repeatedly.\n\n'
text+='### 3. Shared decoder under measured CPU memory contention\n\n'
text+='G=40 uses the previously validated shared stride wrapper so it decodes all 28,584 streams, as does G=1787. Dispatching the original non-stride kernel at G=40 would decode only 640 streams and would not be the same fixed-traffic comparison. The N=0 controls, N=2/4/8/10 campaigns and final N=0 control use the same wrapper and data. Each worker owns two 256,000,000-byte uint8 NumPy arrays (512 MB/thread); repeated np.copyto releases the GIL and streams through arrays far larger than cache. Arrays are allocated/touched before streaming begins, outside measurements; workers stop and their arrays are released after each N campaign. The VM is untouched.\n\n'
text+='Each worker rate is actual complete copy bytes divided by measured elapsed seconds inside those np.copyto calls, using only calls wholly within the row window. CPU traffic=2×copy rate, labeled read+write. Partial boundary copies are excluded, never prorated. The separately retained copied-bytes/window rate is a conservative window-count lower bound. Complete-copy counts, copy-call durations, per-worker intervals and both rate definitions are in raw rows. GPU kernels are timed by GPU timestamps; poisoning and comparisons are outside those timestamps. Both CPU-active-call rates and GPU-only rates omit host gaps, so their sum is a rate sanity check, not a DRAM-counter measurement. The same-wall-window GPU and counted-copy rates are also retained for comparison.\n\n'
text+=table('| N / control | G | Decoder GB/s | CPU copy GB/s | CPU read+write GB/s | GPU+CPU logical GB/s | f_avg / attributed MHz | Foreign % |\n|---|---:|---:|---:|---:|---:|---:|---:|')
cs=[a for a in selected if a['tag'].startswith('contention')]
for a in cs:
 c=a['cpu_contention']; t=a['traffic_sanity']; f=a['gpu_frequency']; ac=a['clock_attribution']
 text+=f"| {a['tag']} | {a['G']} | {a['gbps']['median']:.4f} | {c['cpu_copy_gbps']:.3f} | {c['cpu_traffic_gbps']:.3f} | {t['kernel_rate_plus_cpu_gbps']:.3f} | {f['f_avg_active_mhz']:.1f} / {ac['kernel_attributed_mhz']:.1f} | {100*a['foreign_fraction']:.2f} |\n"
text+=table('| N / control | G | Per-worker measured copy GB/s, worker order 0..N−1 | Full copies counted per worker |\n|---|---:|---|---|')
for a in cs:
 c=a['cpu_contention']; rates=', '.join(f"{w['active_copy_gbps']:.3f}" for w in c['workers']) or 'none'; counts=', '.join(str(w['completed_full_copies']) for w in c['workers']) or 'none'
 text+=f"| {a['tag']} | {a['G']} | {rates} | {counts} |\n"
if cs:
 maxtraffic=max(a['traffic_sanity']['kernel_rate_plus_cpu_gbps'] for a in s['attempts'] if 'traffic_sanity' in a)
 text+=f"\nSanity: shared traffic factor = 1+1/{s['shared_prep']['expansion']:.6f} = {1+1/s['shared_prep']['expansion']:.6f}. For every attempt, GPU kernel median rate × traffic factor + measured CPU read/write rate ≤120 GB/s; maximum observed sum is {maxtraffic:.3f} GB/s. No rejected-over-120 attempt is hidden. This counts logical coded-read/plain-write plus CPU read/write bytes, not physical DRAM transactions/cache/write-allocation overhead.\n\n"
 for g in [40,1787]:
  a=next(x for x in cs if x['tag']=='contention-N0' and x['G']==g); b=next(x for x in cs if x['tag']=='contention-N0-end' and x['G']==g); c=next(x for x in cs if x['tag']=='contention-N10' and x['G']==g)
  text+=f"G={g}: N=10 changes decode from {a['gbps']['median']:.4f} to {c['gbps']['median']:.4f} GB/s ({100*(c['gbps']['median']/a['gbps']['median']-1):.2f}%). Ending N=0 gives {b['gbps']['median']:.4f} GB/s, drift {100*(b['gbps']['median']/a['gbps']['median']-1):+.3f}%.\n\n"
text+='CPU contention degrades decode on this unified-memory host under the recorded background. It does not identify bandwidth as the sole cause: CPU scheduling, shared power/clock and host submission gaps also change, and some attempts fail the P15 coverage threshold and use f_avg-active instead. All per-row foreign-work flags remain visible. vm_stat snapshots are retained before and after each N campaign. Global counters show no new pageouts, swapouts or compressions, but swapins (20–5,238 pages per campaign) and decompressions (92–14,134 pages) occurred. These are shared-machine counters and cannot be assigned solely to the harness. This is a decoder/copy campaign, not an end-to-end model load or inference benchmark.\n\n'
text+='### 2. Fused real BF16\n\n'
if 'fused_prep' in s:
 f=s['fused_prep']; text+=f"Reference is {f['bf16_bytes']:,} original BF16 bytes read directly from the same safetensors tensors, not reconstructed by the tested merge. The independently checked exponent plane matches ref.bin; raw sign/mantissa is ((word>>8)&0x80)|(word&0x7f), {f['smplane_bytes']:,} bytes. Shipped geometry is 128 threads/TG and ceil(28,584/16)=1,787 TGs. Buffers are allocated and populated once before warmups. The source entrypoint expects coded streams at buffer 0, offsets 1, smplane 2, BF16 output 3, shared header 4 and Params 5. The current Objective-C host C ABI does not expose a fused decode function; this harness dispatches the shipped Metal entrypoint directly.\n\n"
text+=table('| Fused arm / G | GPU ms (min–max) | BF16-output GB/s | Exponent-plane GB/s | Compiled TG bytes | Foreign % |\n|---|---:|---:|---:|---:|---:|')
for tag in ['fused-shipped','fused-drift','fused-sweep']:
 for a in sel(tag): text+=f"| {tag} / {a['G']} | {extent(a)} | {a['gbps']['median']:.4f} | {a['exponent_gbps']['median']:.4f} | {a['static_threadgroup_bytes']} | {100*a['foreign_fraction']:.2f} |\n"
if 'fused_drift' in s:
 d=s['fused_drift']; text+=f"\nFull-grid wrapper drift {100*d['relative_drift']:.3f}%; within 3%: {d['pass_3pct']}. Both numerators use the same measured GPU time: BF16_bytes=1,873,281,024 and exponent_bytes=936,640,512. BF16-output GB/s is exactly twice exponent-plane GB/s. This removes the old numerator ambiguity; the historical synthetic 36.3 figure is not represented as real BF16 evidence. Original BF16 byte comparisons run on first and last timed dispatch of every attempt/G, and pass.\n\n"
text+='### Conditions, validation, reproduction and cleanup\n\n'
text+='Each run holds the shared m4-gpu mkdir lock; each lock period is bounded below 20 minutes, and no timed GPU process overlaps another harness. Start idle samples are recorded and rechecked according to the brief. AGXDeviceUserClient before/after counters exclude the harness PID. Above 2% foreign summed GPU time each row is repeated once and both attempts remain append-only; reports select the required retry, not the fastest. Some rows still exceed 2% after retry. In particular, fused G=120 retry has foreign time over three times the timed kernel sum; its rate and P15 attribution are heavily contaminated and retained as flagged evidence, not a clean result. Such rows and the resulting broad cost intervals are conditional on those background conditions, not clean uncontended constants. The clock interval includes measured device-wide state residency; the P15 attribution rule is retained even when background may contribute P15 time.\n\n'
if 'final_tests' in s:
 t=s['final_tests']['final']; text+=f"Final exact pytest baseline: **{t['result']}**. Matches requested 142 passed / 6 skip-as-fail: {t['matches_baseline']}. All attempts are retained in tests-phase4-attempt*.txt and tests-phase4.json; no test handling or shipped-source fixes.\n\n"
text+=f"New raw log: runs-phase4.jsonl ({s['run_rows']} rows, {s['warmup_rows']} warmups, {s['timed_rows']} timed dispatches); original runs.jsonl is preserved. Summary: summary-phase4.json. New host harness: harness_phase4.swift, built by swiftc -O against Foundation/Metal; needs installed Apple developer tools. New wrappers: wrapper_phase4.metal, generated by build_phase4_wrappers.py from shipped source. New prep: prep_phase4.py. Orchestration: measure_phase4.py build/perstream/contention/fused. Clock re-read: attribute_phase4.py. Analysis/render: analyze_phase4.py and render_phase4.py. Reuse the original locked campaign.py prep first. All source paths are relative to the lmz root; use the existing Python environment /Users/masshj/system-env/customize-llm/venv/bin/python. No dependency installs are needed.\n\n"
text+='Tracked-file validation reads the Git index directly without invoking git. Initial tracked-phase4-initial.json records the original report prefix length/hash; final validation permits only this requested report append and requires the prefix hash to match. Shipped sources remain byte-identical to the index. Cached data remain available for review; no cleanup is performed.\n\nNew/recreated external cache artifacts for user cleanup:\n\n'
