 report=ROOT/'docs/evaluations/m4-metal-decoder-remeasure.md'; before=json.loads((HERE/'tracked-phase4-initial.json').read_text()); raw=report.read_bytes()
 assert len(raw)==before['report_prefix_length'] and hashlib.sha256(raw).hexdigest()==before['report_prefix_sha256'],'refuse duplicate append or changed report prefix'
